    // Enum wire-value lock: enum members must round-trip as their OpenAPI wire
    // string (e.g. "available"), NOT the C# member name ("Available"). Each
    // generated enum carries its own [JsonConverter] that maps to the wire
    // value; this guards against a global converter shadowing it (per the
    // System.Text.Json rule that an options-registered converter outranks a
    // type-level [JsonConverter] attribute). Canonical across all 12 SDKs.
    public class EnumWireValueTests
    {
        private readonly ObjectSerializer _serializer = new();

        [Fact]
        public void BhvSerializationobject119EnumSerializesToWireValue()
        {
            var order = new Order { Status = Order.StatusEnum.Approved };
            var json = _serializer.Serialize(order);
            Assert.Contains("\"status\":\"approved\"", json, StringComparison.Ordinal);
        }

        [Fact]
        public void BhvSerializationobject069EnumDeserializesFromWireValue()
        {
            var order = _serializer.Deserialize<Order>("{\"status\":\"delivered\"}");
            Assert.Equal(Order.StatusEnum.Delivered, order!.Status);
        }

        [Fact]
        public void BhvSerializationobject022EnumRoundTripsWireValue()
        {
            var order = _serializer.Deserialize<Order>("{\"status\":\"placed\"}");
            var back = _serializer.Serialize(order);
            Assert.Contains("\"status\":\"placed\"", back, StringComparison.Ordinal);
        }

        [Fact]
        public void BhvSerializationobject053DeserializeAppliesSchemaDefaultForAbsentField()
        {
            // Order.status has schema `default: placed`. When the JSON response
            // omits "status", the deserialized model must populate it with the
            // schema default rather than leaving it null. The generated model
            // initializes the property to StatusEnum.Placed and, because the
            // field is optional, that initializer survives deserialization.
            // Canonical across all 12 SDKs.
            var order = _serializer.Deserialize<Order>("{\"id\":10,\"petId\":198772}");
            Assert.NotNull(order);
            Assert.Equal(Order.StatusEnum.Placed, order!.Status);
        }

        [Fact]
        public void BhvSerializationobject025DefaultsAbsentFieldsTakeSchemaDefaultExplicitNullIsPreserved()
        {
            // default-vs-explicit-null contract: a schema `default` applies ONLY
            // when the property is ABSENT from the payload. An explicit JSON null
            // is a provided value and must be PRESERVED (the field stays null),
            // not replaced by the default. Exercised against the dedicated
            // Defaults model (retries/mode/label), matching go/rust/python/node.
            var fromEmpty = _serializer.Deserialize<Defaults>("{}");
            Assert.NotNull(fromEmpty);
            Assert.Equal(3, fromEmpty!.Retries);
            Assert.Equal(Defaults.ModeEnum.Medium, fromEmpty.Mode);
            Assert.Equal("untitled", fromEmpty.Label);
            Assert.Equal("it's \"quoted\" \\ back\tslash\nnext $USD #{x} a*/b", fromEmpty.Greeting);

            var fromNull = _serializer.Deserialize<Defaults>("{\"label\":null,\"retries\":7}");
            Assert.NotNull(fromNull);
            Assert.Null(fromNull!.Label);
            Assert.Equal(7, fromNull.Retries);
            // mode was absent, so it keeps the schema default.
            Assert.Equal(Defaults.ModeEnum.Medium, fromNull.Mode);
        }

        [Fact]
        public void BhvSerializationobject111DefaultsNumericLiteralsKeepTheirExactTypedValue()
        {
            var fromEmpty = _serializer.Deserialize<Defaults>("{}");
            Assert.NotNull(fromEmpty);
            Assert.Equal(1.5m, fromEmpty!.Ratio);
            Assert.Equal(0.25f, fromEmpty.Scale);
            Assert.Equal(2.0, fromEmpty.Weight);
            Assert.Equal(9000000000L, fromEmpty.Ceiling);
        }
    }

    // Gap #13 — discard nulls on serialize.
    // The ObjectSerializer's default JsonSerializerOptions configures
    // DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull so
    // properties whose value is null are omitted from the JSON payload.
    public class NullPropertyOmissionOnSerializeTests
