    public class TimeOnlyAndDurationTests
    {
        private readonly ObjectSerializer _serializer = new();

        [Fact]
        public void TimeOnlyStringifiesAsHourMinuteSecond()
        {
            var t = new TimeOnly(9, 30, 15);
            Assert.Equal("09:30:15", ObjectSerializer.Stringify(t));
        }

        [Fact]
        public void BhvSerializationobject164TimeOnlyKeepsMillisecondsOnlyWhenNonZero()
        {
            Assert.Equal("10:30:00", ObjectSerializer.Stringify(new TimeOnly(10, 30, 0)));
            Assert.Equal("10:30:00.123", ObjectSerializer.Stringify(new TimeOnly(10, 30, 0, 123)));
            Assert.Equal("10:30:00.050", ObjectSerializer.Stringify(new TimeOnly(10, 30, 0, 50)));
        }

        [Fact]
        public void TimeOnlyTruncatesBelowTheMillisecond()
        {
            Assert.Equal(
                "10:30:00.123",
                ObjectSerializer.Stringify(new TimeOnly(10, 30, 0, 123, 456))
            );
            Assert.Equal(
                "10:30:00.999",
                ObjectSerializer.Stringify(new TimeOnly(10, 30, 0, 999, 600))
            );
            Assert.Equal("10:30:00", ObjectSerializer.Stringify(new TimeOnly(10, 30, 0, 0, 900)));
        }

        [Fact]
        public void BhvSerializationobject163TimeOnlyBodyPropertyUsesTheSameWireText()
        {
            var edgeCases = new EdgeCases { Cutoff = new TimeOnly(10, 30, 0, 123, 456) };

            string json = _serializer.Serialize(edgeCases);

            Assert.Contains("\"cutoff\":\"10:30:00.123\"", json, StringComparison.Ordinal);
            Assert.Equal(
                new TimeOnly(10, 30, 0, 123),
                _serializer.Deserialize<EdgeCases>(json)!.Cutoff
            );
            Assert.Equal(
                new TimeOnly(10, 30, 0),
                _serializer.Deserialize<EdgeCases>("{\"cutoff\":\"10:30:00\"}")!.Cutoff
            );
        }

        [Fact]
        public void TimeOnlyBodyPropertyRejectsAMalformedTime()
        {
            Assert.Throws<SerializationException>(() =>
                _serializer.Deserialize<EdgeCases>("{\"cutoff\":\"not-a-time\"}")
            );
        }

        [Fact]
        public void BhvSerializationobject158TimeSpanStringifiesAsProtobufDuration()
        {
            // 1h30m → 5400 seconds → "5400s"
            var ts = new TimeSpan(1, 30, 0);
            Assert.Equal("5400s", ObjectSerializer.Stringify(ts));
        }

        [Fact]
        public void BhvSerializationobject181TimeSpanZeroStringifiesAs0s()
        {
            Assert.Equal("0s", ObjectSerializer.Stringify(TimeSpan.Zero));
        }

        [Fact]
        public void BhvSerializationobject081FormatProtobufDurationEmitsWholeSeconds()
        {
            Assert.Equal("90s", ProtobufDurationConverter.Format(TimeSpan.FromSeconds(90)));
        }

        [Fact]
        public void BhvSerializationobject105NegativeDurationCarriesTheSign()
        {
            Assert.Equal("-90s", ProtobufDurationConverter.Format(TimeSpan.FromSeconds(-90)));
        }

        [Fact]
        public void BhvSerializationobject106NegativeFractionalDurationCarriesTheSign()
        {
            Assert.Equal(
                "-1.500s",
                ProtobufDurationConverter.Format(TimeSpan.FromMilliseconds(-1500))
            );
        }

        [Fact]
        public void BhvSerializationobject112DurationConverterRoundTripWholeSeconds()
        {
            // 2h15m30s → 8130 seconds → "8130s"
            var original = new TimeSpan(2, 15, 30);
            string formatted = ProtobufDurationConverter.Format(original);
            Assert.Equal("8130s", formatted);
            TimeSpan parsed = ProtobufDurationConverter.Parse(formatted);
            Assert.Equal(original, parsed);
        }

        [Fact]
        public void DurationConverterRoundTripDaysAndTime()
        {
            // 3d4h5m6s → 273906 seconds → "273906s"
            var original = new TimeSpan(3, 4, 5, 6);
            string formatted = ProtobufDurationConverter.Format(original);
            Assert.Equal("273906s", formatted);
            Assert.Equal(original, ProtobufDurationConverter.Parse(formatted));
        }

        [Fact]
        public void BhvSerializationobject073DurationConverterRoundTripNegative()
        {
            var original = new TimeSpan(0, -45, 0);
            string formatted = ProtobufDurationConverter.Format(original);
            Assert.Equal("-2700s", formatted);
            Assert.Equal(original, ProtobufDurationConverter.Parse(formatted));
        }

        [Fact]
        public void BhvSerializationobject045DurationConverterFormatsSubSecondPrecision()
        {
            // 1 tick = 100ns → 9-digit fraction "3600.000000100s"
            var oneHourPlusTick = TimeSpan.FromHours(1) + TimeSpan.FromTicks(1);
            Assert.Equal("3600.000000100s", ProtobufDurationConverter.Format(oneHourPlusTick));

            // Millisecond fraction trims to 3 digits (protobuf emits 3/6/9).
            Assert.Equal(
                "1.500s",
                ProtobufDurationConverter.Format(TimeSpan.FromMilliseconds(1500))
            );
        }

        [Fact]
        public void BhvSerializationobject054DurationConverterParsesFractionalSeconds()
        {
            TimeSpan parsed = ProtobufDurationConverter.Parse("1.5s");
            Assert.Equal(TimeSpan.FromMilliseconds(1500), parsed);
        }

        [Fact]
        public void DurationConverterParsesNanosecondFraction()
        {
            // "3600.000000001s" rounds to 0 ticks of fraction (100ns resolution).
            TimeSpan parsed = ProtobufDurationConverter.Parse("3600.000000001s");
            Assert.Equal(TimeSpan.FromHours(1), parsed);
            // "3600.000000100s" is exactly one tick beyond an hour.
            TimeSpan parsedTick = ProtobufDurationConverter.Parse("3600.000000100s");
            Assert.Equal(TimeSpan.FromHours(1) + TimeSpan.FromTicks(1), parsedTick);
        }

        [Fact]
        public void BhvSerializationobject066DurationConverterRejectsInvalid()
        {
            Assert.Throws<System.Text.Json.JsonException>(() =>
                ProtobufDurationConverter.Parse("not-a-duration")
            );
            // missing 's' suffix
            Assert.Throws<System.Text.Json.JsonException>(() =>
                ProtobufDurationConverter.Parse("3600")
            );
            // bare integer (protobuf number, not the string form)
            Assert.Throws<System.Text.Json.JsonException>(() =>
                ProtobufDurationConverter.Parse("18000.000000000")
            );
        }

        [Fact]
        public void DurationConverterRejectsIso8601()
        {
            // ISO-8601 durations are rejected by protobuf/gRPC-gateway backends.
            Assert.Throws<System.Text.Json.JsonException>(() =>
                ProtobufDurationConverter.Parse("PT1H")
            );
            Assert.Throws<System.Text.Json.JsonException>(() =>
                ProtobufDurationConverter.Parse("P1Y")
            );
        }

        [Fact]
        public void DurationSerializesThroughObjectSerializer()
        {
            var ts = new TimeSpan(1, 30, 0);
            string json = _serializer.Serialize(ts);
            Assert.Equal("\"5400s\"", json);
        }

        [Fact]
        public void BhvSerializationobject113DurationDeserializesThroughObjectSerializer()
        {
            TimeSpan ts = _serializer.Deserialize<TimeSpan>("\"8100s\"");
            Assert.Equal(new TimeSpan(2, 15, 0), ts);
        }

        [Fact]
        public void DurationFullRoundTripThroughObjectSerializer()
        {
            var original = new TimeSpan(1, 2, 30, 45);
            string json = _serializer.Serialize(original);
            TimeSpan parsed = _serializer.Deserialize<TimeSpan>(json);
            Assert.Equal(original, parsed);
        }

        [Theory]
        [InlineData("\"99999999999999999999s\"")] // does not fit a long
        [InlineData("\"999999999999s\"")] // fits a long, overflows TimeSpan ticks
        [InlineData("\"\u0661\u0662s\"")] // non-ASCII digits
        public void BhvSerializationobject080MalformedOrOverflowingDurationRaisesSerializationException(
            string json
        )
        {
            // Neither a raw FormatException/OverflowException nor a silently
            // wrapped tick count: the caller sees the SDK's own error.
            var ex = Assert.Throws<SerializationException>(() =>
                _serializer.Deserialize<TimeSpan>(json)
            );
            Assert.IsAssignableFrom<OpenAPIException>(ex);
        }
    }

