                    ("Sold", Availability.Sold),
                    ("on-hold", Availability.OnHold),
                }
            )
            {
                var payload = "{\"priority\":1,\"availability\":\"" + wire + "\"}";
                var item = _serializer.Deserialize<StockItem>(payload);
                Assert.Equal(member, item!.Availability);
                Assert.Contains(
                    "\"availability\":\"" + wire + "\"",
